async function seedJobs() {
    try {
        const mongoUri = process.env.MONGO_URI || 'mongodb://127.0.0.1:27017/connecta';
        console.log(`🌱 Connecting to MongoDB at ${mongoUri}...`);
        await mongoose.connect(mongoUri);
        // Find or create a default client user to own these jobs
        let client = await User.findOne({ userType: 'client' });
        if (!client) {
            client = await User.create({
                firstName: 'Connecta',
                lastName: 'Client',
                email: 'client@connecta.ng',
                password: '$2a$10$eM9s...hashedPasswordPlaceholder',
                userType: 'client',
                isVerified: true,
            });
            console.log('👤 Created default client user for job postings:', client.email);
        }
        console.log('🧹 Clearing existing sample jobs...');
        await Job.deleteMany({});
        const jobsToInsert = SAMPLE_JOBS.map((j) => ({
            ...j,
            clientId: client._id,
            status: 'active',
            createdAt: new Date(Date.now() - Math.floor(Math.random() * 7 * 24 * 60 * 60 * 1000)),
        }));
        const inserted = await Job.insertMany(jobsToInsert);
        console.log(`✅ Successfully seeded ${inserted.length} sample jobs into database!`);
        await mongoose.disconnect();
        process.exit(0);
    }
    catch (err) {
        console.error('❌ Error seeding jobs:', err);
        process.exit(1);
    }
}
seedJobs();
